from files import artifact_name, group_by_extension, swap_extension


def test_artifact_name_final_extension_only():
    assert artifact_name("a/b/report.tar.gz") == "report.tar"
    assert artifact_name("build/output.log") == "output"
    assert artifact_name("Makefile") == "Makefile"


def test_artifact_name_dotfiles_unchanged():
    assert artifact_name(".bashrc") == ".bashrc"
    assert artifact_name("home/user/.gitignore") == ".gitignore"


def test_swap_extension():
    assert swap_extension("logs/app.log", ".txt") == "logs/app.txt"
    assert swap_extension("archive.tar.gz", ".bz2") == "archive.tar.bz2"
    assert swap_extension("Makefile", ".bak") == "Makefile.bak"


def test_group_by_extension():
    got = group_by_extension(
        ["src/a.py", "src/b.py", "notes.txt", "Makefile", "pkg/data.tar.gz"]
    )
    assert got == {
        ".py": ["a.py", "b.py"],
        ".txt": ["notes.txt"],
        "": ["Makefile"],
        ".gz": ["data.tar.gz"],
    }

